    page.on('requestfailed', req => { const method = req.url().match(/\/(sendDocument|editMessageMedia)(?:[?]|$)/)?.[1]; if (method) console.log('M7_LEAVE_DIAG', JSON.stringify({ event: 'requestfailed', method, error: req.failure()?.errorText, at: Date.now() })); });
