// 3.54.0: echtes Signalpanel, BTC, Originalpositionen, Journal und isolierte Teil-Ausfälle.
const h = require('./harness'); let pass = 0, fail = 0; const check = (name, ok, detail = '') => { ok ? pass++ : fail++; console.log(`${ok ? '✓' : '✗'} ${name}${detail ? ' — ' + detail : ''}`); };
(async () => { let browser;
  try {
